-- GWizard Postgres Export
-- Generated based on extracted logic and parameters

BEGIN;

CREATE TABLE IF NOT EXISTS material_families (
    id SERIAL PRIMARY KEY,
    name VARCHAR(255) UNIQUE NOT NULL,
    metadata JSONB DEFAULT '{}'::jsonb
);
CREATE TABLE IF NOT EXISTS machinability (
    family_id INTEGER REFERENCES material_families(id) ON DELETE CASCADE PRIMARY KEY,
    machinability_factor NUMERIC,
    density NUMERIC,
    min_bhn INTEGER,
    max_bhn INTEGER,
    dry_multiplier NUMERIC,
    sfm_range INTEGER,
    sfm_range_hss INTEGER,
    cexp NUMERIC,
    coating_rec VARCHAR(255),
    drill_style VARCHAR(255),
    point_style VARCHAR(255),
    point_angle VARCHAR(255),
    thread_mill NUMERIC,
    pcd_em NUMERIC
);
CREATE TABLE IF NOT EXISTS specific_alloys (
    id SERIAL PRIMARY KEY,
    family_id INTEGER REFERENCES material_families(id) ON DELETE CASCADE,
    alloy_name VARCHAR(255),
    condition VARCHAR(255),
    hardness VARCHAR(255),
    metadata JSONB DEFAULT '{}'::jsonb
);
CREATE TABLE IF NOT EXISTS tool_types (
    id SERIAL PRIMARY KEY,
    label VARCHAR(255) UNIQUE NOT NULL,
    is_lathe BOOLEAN,
    is_mill BOOLEAN,
    is_carbide BOOLEAN,
    chip_thinning BOOLEAN,
    has_coating BOOLEAN,
    metadata JSONB DEFAULT '{}'::jsonb
);
CREATE TABLE IF NOT EXISTS sfm_data (
    family_id INTEGER REFERENCES material_families(id) ON DELETE CASCADE,
    tool_type_id INTEGER REFERENCES tool_types(id) ON DELETE CASCADE,
    base_sfm NUMERIC,
    tsc_multiplier NUMERIC,
    PRIMARY KEY(family_id, tool_type_id)
);
CREATE TABLE IF NOT EXISTS ipt_data (
    family_id INTEGER REFERENCES material_families(id) ON DELETE CASCADE,
    tool_type_id INTEGER REFERENCES tool_types(id) ON DELETE CASCADE,
    d_0_0625 NUMERIC,
    d_0_125 NUMERIC,
    d_0_1875 NUMERIC,
    d_0_25 NUMERIC,
    d_0_375 NUMERIC,
    d_0_5 NUMERIC,
    d_0_75 NUMERIC,
    d_1_0 NUMERIC,
    d_1_5 NUMERIC,
    d_2_0 NUMERIC,
    d_3_0 NUMERIC,
    d_4_0 NUMERIC,
    d_5_0 NUMERIC,
    PRIMARY KEY(family_id, tool_type_id)
);







SELECT setval('material_families_id_seq', 32);
SELECT setval('tool_types_id_seq', 37);

COMMIT;